using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using TourCore.Application.Abstractions;
using TourCore.Application.Abstractions.Persistence;
using TourCore.Application.Abstractions.Persistence.Tours;
using TourCore.Application.Abstractions.Services;
using TourCore.Application.Common.Errors;
using TourCore.Application.Common.Exceptions;
using TourCore.Application.Common.Queries;
using TourCore.Contracts.Common;
using TourCore.Contracts.Tours;
using TourCore.Domain.Tours;
namespace TourCore.Application.Tours
{
 public class CreateTourTypeHandler:ICommandHandler<CreateTourTypeCommand,TourTypeDto>{private readonly ITourTypeRepository r;private readonly IUnitOfWork u;private readonly IDateTimeProvider clock;private readonly TourTypeCommandValidator v;public CreateTourTypeHandler(ITourTypeRepository r,IUnitOfWork u,IDateTimeProvider clock,TourTypeCommandValidator v){this.r=r;this.u=u;this.clock=clock;this.v=v;}public async Task<TourTypeDto> Handle(CreateTourTypeCommand c,CancellationToken ct){v.ValidateAndThrow(c.Name,c.ParentId);if(c.ParentId.HasValue&&await r.GetByIdAsync(c.ParentId.Value,ct)==null)throw new NotFoundException(ErrorMessages.TourTypeParentNotFound,ErrorCode.TourTypeParentNotFound);if(await r.ExistsByNameAsync(c.Name.Trim(),null,ct))throw new ConflictException(ErrorMessages.TourTypeNameExists,ErrorCode.TourTypeNameExists);var e=new TourType(c.Name,c.ParentId,clock.UtcNow);await r.AddAsync(e,ct);await u.SaveChangesAsync(ct);return e.ToDto();}}
 public class UpdateTourTypeHandler:ICommandHandler<UpdateTourTypeCommand,TourTypeDto>{private readonly ITourTypeRepository r;private readonly IUnitOfWork u;private readonly IDateTimeProvider clock;private readonly TourTypeCommandValidator v;public UpdateTourTypeHandler(ITourTypeRepository r,IUnitOfWork u,IDateTimeProvider clock,TourTypeCommandValidator v){this.r=r;this.u=u;this.clock=clock;this.v=v;}public async Task<TourTypeDto> Handle(UpdateTourTypeCommand c,CancellationToken ct){v.ValidateAndThrow(c.Name,c.ParentId);var e=await r.GetByIdAsync(c.Id,ct);if(e==null)throw new NotFoundException(ErrorMessages.TourTypeNotFound,ErrorCode.TourTypeNotFound);if(c.ParentId.HasValue){if(await r.GetByIdAsync(c.ParentId.Value,ct)==null)throw new NotFoundException(ErrorMessages.TourTypeParentNotFound,ErrorCode.TourTypeParentNotFound);if(c.ParentId==c.Id||await r.IsDescendantAsync(c.Id,c.ParentId.Value,ct))throw new ConflictException(ErrorMessages.TourTypeCycle,ErrorCode.TourTypeCycle);}if(await r.ExistsByNameAsync(c.Name.Trim(),c.Id,ct))throw new ConflictException(ErrorMessages.TourTypeNameExists,ErrorCode.TourTypeNameExists);e.Update(c.Name,c.ParentId,clock.UtcNow);await u.SaveChangesAsync(ct);return e.ToDto();}}
 public class DeleteTourTypeHandler:ICommandHandler<DeleteTourTypeCommand,bool>{private readonly ITourTypeRepository r;private readonly IUnitOfWork u;public DeleteTourTypeHandler(ITourTypeRepository r,IUnitOfWork u){this.r=r;this.u=u;}public async Task<bool> Handle(DeleteTourTypeCommand c,CancellationToken ct){var e=await r.GetByIdAsync(c.Id,ct);if(e==null)throw new NotFoundException(ErrorMessages.TourTypeNotFound,ErrorCode.TourTypeNotFound);if(await r.HasChildrenAsync(c.Id,ct))throw new ConflictException(ErrorMessages.TourTypeHasChildren,ErrorCode.TourTypeHasChildren);if(await r.IsUsedAsync(c.Id,ct))throw new ConflictException(ErrorMessages.TourTypeIsUsed,ErrorCode.TourTypeIsUsed);r.Remove(e);await u.SaveChangesAsync(ct);return true;}}
 public class GetTourTypeByIdHandler:IQueryHandler<GetTourTypeByIdQuery,TourTypeDto>{private readonly ITourTypeRepository r;public GetTourTypeByIdHandler(ITourTypeRepository r){this.r=r;}public async Task<TourTypeDto> Handle(GetTourTypeByIdQuery q,CancellationToken ct){var e=await r.GetByIdAsync(q.Id,ct);if(e==null)throw new NotFoundException(ErrorMessages.TourTypeNotFound,ErrorCode.TourTypeNotFound);return e.ToDto();}}
 public class GetTourTypesHandler:IQueryHandler<GetTourTypesQuery,PagedResponseDto<TourTypeListItemDto>>{private readonly ITourTypeRepository r;private readonly PagedQueryExecutor p;public GetTourTypesHandler(ITourTypeRepository r,PagedQueryExecutor p){this.r=r;this.p=p;}public async Task<PagedResponseDto<TourTypeListItemDto>> Handle(GetTourTypesQuery q,CancellationToken ct){q=q??new GetTourTypesQuery();var x=r.Query();if(!string.IsNullOrWhiteSpace(q.Search)){var s=q.Search.Trim();x=x.Where(t=>t.Name.Contains(s));}if(q.RootOnly==true)x=x.Where(t=>t.ParentId==null);else if(q.ParentId.HasValue)x=x.Where(t=>t.ParentId==q.ParentId);var z=await p.ExecuteAsync(x.OrderBy(t=>t.Name).Select(t=>new TourTypeListItemDto{Id=t.Id,Name=t.Name,ParentId=t.ParentId}),q,ct);return new PagedResponseDto<TourTypeListItemDto>(z.Items,z.Page,z.PageSize,z.TotalCount);}}
}
